add_filter( 'woocommerce_valid_order_statuses_for_order_again', 'perfectpixel_order_again_for_more_statuses' );

function perfectpixel_order_again_for_more_statuses( $statuses ) {
	$extra = array_filter( array_map( 'sanitize_key', explode( ',', '{{order_again_statuses}}' ) ) );
	return array_values( array_unique( array_merge( (array) $statuses, $extra ) ) );
}
